//! The sink rules against the INTdfm rule layer's own answers.
//!
//! Each fixture is one input the Python rule layer saw, plus the findings it returned:
//!
//! * the real cases are schema-2 recordings, narrowed to the facts these rules read;
//! * the cases marked `test_only` edit those facts (a moved hole, a declared dimension, a
//!   countersink) because no recording has that shape, and the expected findings are still
//!   `rules.py`'s output for that input, generated by the script in the fixture README.
//!
//! This compares what a fixture can pin: the status, `error_code`, `reason_code`, measured value,
//! chosen limit and layer, and the rule list of every finding, in order. Messages are not compared
//! byte for byte (Rust has no `:g`), and neither is `needs`, which follows INTdfm's wording.

use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use solidcraft_dfm_rules::sink_rules::{countersink_findings, hole_spacing, tolerance_across_bends};
use solidcraft_dfm_rules::{CheckInput, Critical, Declared, Facts, Feature, Finding, Layer, ModelRef, Profile, RuleStatus};

#[derive(Deserialize)]
struct Fixture {
    source: Source,
    case: Case,
    input: Input,
    expected: Expected,
}

#[derive(Deserialize)]
struct Source {
    intdfm_commit: String,
    core_source_sha256: String,
    base_recording: String,
}

#[derive(Deserialize)]
struct Case {
    id: String,
    description: String,
    group: String,
    flat: bool,
    test_only: bool,
    #[serde(default)]
    report_checked: Option<bool>,
}

#[derive(Deserialize)]
struct Input {
    declared: Declared,
    generic: Profile,
    shop: Option<Profile>,
    facts: Facts,
    #[serde(default)]
    critical: Vec<Critical>,
    thickness_gate: PyFinding,
    bends_gate: PyFinding,
}

#[derive(Deserialize)]
struct Expected {
    findings: Vec<PyFinding>,
}

/// An INTdfm finding, only as far as this test compares it.
#[derive(Deserialize)]
struct PyFinding {
    rules: Vec<String>,
    status: RuleStatus,
    error_code: Option<String>,
    reason_code: Option<String>,
    message: String,
    measured: Option<PyQuantity>,
    requirement: Option<PyRequirement>,
    #[serde(default)]
    needs: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct PyQuantity {
    value: f64,
    #[allow(dead_code)]
    unit: String,
}

#[derive(Debug, Deserialize)]
struct PyRequirement {
    value: Option<PyQuantity>,
    layer: Layer,
    #[serde(default)]
    #[allow(dead_code)]
    source: String,
    #[serde(default)]
    #[allow(dead_code)]
    text: String,
}

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/sink")
}

fn fixture(id: &str) -> Fixture {
    let path = fixtures_dir().join(format!("{id}.json"));
    let text = fs::read_to_string(&path).unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|error| panic!("parse {}: {error}", path.display()))
}

fn gate(finding: &PyFinding) -> Finding {
    Finding {
        id: String::new(),
        rules: finding.rules.clone(),
        status: finding.status,
        state: solidcraft_dfm_rules::AppState::Unsupported,
        error_code: finding.error_code.clone(),
        reason_code: finding.reason_code.clone(),
        message: finding.message.clone(),
        feature: Feature { kind: "sheet".into(), number: None, description: "the sheet".into() },
        location: None,
        measured_mm: finding.measured.as_ref().map(|quantity| quantity.value),
        requirement: None,
        needs: finding.needs.clone(),
    }
}

fn run(fixture: &Fixture) -> Vec<Finding> {
    let input = CheckInput {
        declared: fixture.input.declared.clone(),
        generic: fixture.input.generic.clone(),
        shop: fixture.input.shop.clone(),
        overrides: Vec::new(),
        facts: fixture.input.facts.clone(),
        model: ModelRef::default(),
        critical: fixture.input.critical.clone(),
    };
    let thickness = gate(&fixture.input.thickness_gate);
    let bends = gate(&fixture.input.bends_gate);
    match fixture.case.group.as_str() {
        "spacing" => hole_spacing(&input, &thickness),
        "tolerance" => tolerance_across_bends(&input, &thickness, &bends, fixture.case.flat),
        "countersinks" => countersink_findings(&input, &thickness, &bends, fixture.case.flat),
        other => panic!("{}: unknown rule group {other}", fixture.case.id),
    }
}

fn close(left: f64, right: f64, what: &str, id: &str) {
    assert!((left - right).abs() <= 1e-9, "{id}: {what}: rust {left}, python {right}");
}

fn compare(fixture: &Fixture, actual: &[Finding]) {
    let expected = &fixture.expected.findings;
    assert_eq!(actual.len(), expected.len(), "{}: finding count", fixture.case.id);
    for (index, (got, wanted)) in actual.iter().zip(expected.iter()).enumerate() {
        let id = format!("{} #{}", fixture.case.id, index + 1);
        assert_eq!(got.rules, wanted.rules, "{id}: rules");
        assert_eq!(got.status, wanted.status, "{id}: status");
        assert_eq!(got.error_code, wanted.error_code, "{id}: error code");
        assert_eq!(got.reason_code, wanted.reason_code, "{id}: reason code");
        assert!(!got.message.is_empty(), "{id}: every finding says something");
        match (&wanted.measured, got.measured_mm) {
            (Some(wanted), Some(got)) => close(got, wanted.value, "measured", &id),
            (None, None) => {}
            (wanted, got) => panic!("{id}: measured is {got:?}, expected {wanted:?}"),
        }
        match (&wanted.requirement, &got.requirement) {
            (None, None) => {}
            (Some(wanted), Some(got)) => {
                assert_eq!(got.layer, wanted.layer, "{id}: requirement layer");
                match &wanted.value {
                    Some(value) => close(got.value_mm, value.value, "limit", &id),
                    None => panic!("{id}: the fixture's requirement has no value"),
                }
            }
            (wanted, got) => panic!("{id}: requirement is {got:?}, expected {wanted:?}"),
        }
    }
}

fn check(id: &str) {
    let fixture = fixture(id);
    assert_eq!(fixture.case.id, id);
    assert!(!fixture.source.intdfm_commit.is_empty());
    assert_eq!(fixture.source.core_source_sha256.len(), 64);
    assert!(!fixture.source.base_recording.is_empty());
    assert!(!fixture.case.description.is_empty());
    compare(&fixture, &run(&fixture));
}

macro_rules! fixture_cases {
    ($($test:ident => $id:literal),* $(,)?) => {
        $(#[test]
        fn $test() {
            check($id);
        })*

        const FIXTURE_IDS: &[&str] = &[$($id),*];
    };
}

fixture_cases! {
    real_spacing_plate_holes => "real.spacing_plate_holes",
    real_spacing_u_holes => "real.spacing_u_holes",
    real_spacing_no_pair => "real.spacing_no_pair",
    real_spacing_opening => "real.spacing_opening",
    real_spacing_step_failed => "real.spacing_step_failed",
    real_spacing_missing_thickness => "real.spacing_missing_thickness",
    synthetic_spacing_wall_review => "synthetic.spacing_wall_review",
    synthetic_spacing_d_shop => "synthetic.spacing_d_shop",
    real_tolerance_not_declared => "real.tolerance_not_declared",
    synthetic_tolerance_rows => "synthetic.tolerance_rows",
    synthetic_tolerance_public => "synthetic.tolerance_public",
    synthetic_tolerance_unrecognised => "synthetic.tolerance_unrecognised",
    synthetic_tolerance_bend_gate => "synthetic.tolerance_bend_gate",
    real_countersinks_none => "real.countersinks_none",
    real_countersinks_step_failed => "real.countersinks_step_failed",
    synthetic_countersinks_flat => "synthetic.countersinks_flat",
    synthetic_countersinks_review => "synthetic.countersinks_review",
    synthetic_countersinks_bent => "synthetic.countersinks_bent",
}

/// A fixture without a test, or a test without its fixture, fails here.
#[test]
fn every_fixture_has_exactly_one_case() {
    let mut found: Vec<String> = fs::read_dir(fixtures_dir())
        .expect("fixtures folder")
        .map(|entry| entry.expect("a directory entry").file_name().into_string().expect("a UTF-8 file name"))
        .filter(|name| name.ends_with(".json"))
        .map(|name| name.trim_end_matches(".json").to_string())
        .collect();
    found.sort();
    let mut named: Vec<String> = FIXTURE_IDS.iter().map(|id| (*id).to_string()).collect();
    named.sort();
    assert_eq!(found, named);
}

/// At least one real case is also checked against the recording's own `expected.report`, so the
/// report cross-check is exercised rather than described.
#[test]
fn a_real_case_matches_the_recorded_report() {
    assert!(FIXTURE_IDS.iter().any(|id| fixture(id).case.report_checked == Some(true)), "no fixture was checked against expected.report");
    for id in FIXTURE_IDS {
        let fixture = fixture(id);
        if fixture.case.report_checked == Some(true) {
            assert!(!fixture.case.test_only, "{id}: only a real recording has a report to check");
        }
    }
}

/// Every `test_only` fixture says so, and every real one names a recording.
#[test]
fn synthetic_fixtures_are_labelled() {
    for id in FIXTURE_IDS {
        let fixture = fixture(id);
        let synthetic = id.starts_with("synthetic.");
        assert_eq!(fixture.case.test_only, synthetic, "{id}: test_only must match the synthetic prefix");
        assert_eq!(fixture.case.description.starts_with("TEST-ONLY:"), synthetic, "{id}: a synthetic case says TEST-ONLY");
    }
}

fn codes(findings: &[Finding]) -> Vec<&str> {
    findings.iter().filter_map(|finding| finding.error_code.as_deref().or(finding.reason_code.as_deref())).collect()
}

// ---------------------------------------------------------------------------
// Injected wrong numbers: each must produce the exact code the rule layer names.

#[test]
fn a_wider_wall_clears_the_spacing_number() {
    let mut fixture = fixture("synthetic.spacing_wall_review");
    assert!(codes(&run(&fixture)).contains(&"HOLE_SPACING_BELOW_LIMIT"));
    // Put hole 2 back where the recording has it: every wall is then 2t or more.
    fixture.input.facts.holes.as_mut().expect("holes")[1].x_mm = 20.0;
    let findings = run(&fixture);
    assert!(!codes(&findings).contains(&"HOLE_SPACING_BELOW_LIMIT"), "{:?}", codes(&findings));
    assert!(findings.iter().any(|finding| finding.reason_code.as_deref() == Some("ABOVE_PUBLIC_VALUE")));
}

#[test]
fn a_looser_table_row_turns_the_tolerance_pass_into_a_review() {
    let mut fixture = fixture("synthetic.tolerance_rows");
    assert!(run(&fixture).iter().any(|finding| finding.status == RuleStatus::Pass));
    for row in &mut fixture.input.shop.as_mut().expect("shop").requirements {
        if row.bends == Some(vec![Some(1), Some(1)]) {
            row.value.insert("mm".to_string(), 0.5);
        }
    }
    let findings = run(&fixture);
    assert!(!findings.iter().any(|finding| finding.status == RuleStatus::Pass), "{:?}", codes(&findings));
    assert!(codes(&findings).contains(&"TOLERANCE_TIGHTER_THAN_SHOP"));
}

#[test]
fn a_table_with_no_row_for_those_bends_has_no_number() {
    let mut fixture = fixture("synthetic.tolerance_rows");
    for row in &mut fixture.input.shop.as_mut().expect("shop").requirements {
        row.bends = Some(vec![Some(0), Some(0)]);
    }
    let findings = run(&fixture);
    // The pass and the tighter review both cross one bend and now have no row: no number.
    assert!(codes(&findings).contains(&"NO_SHOP_NUMBER"), "{:?}", codes(&findings));
}

#[test]
fn a_deeper_countersink_and_a_nearer_edge_fail_their_numbers() {
    let mut fixture = fixture("synthetic.countersinks_flat");
    let sink = fixture.input.facts.holes.as_mut().expect("holes")[0].countersink.as_mut().expect("a countersink");
    sink.depth_mm = 2.5;
    sink.edge_mm = Some(1.0);
    let findings = run(&fixture);
    let found = codes(&findings);
    assert!(found.contains(&"COUNTERSINK_DEPTH_ABOVE_LIMIT"), "{found:?}");
    assert!(found.contains(&"COUNTERSINK_EDGE_BELOW_LIMIT"), "{found:?}");
}

#[test]
fn a_smaller_bend_gap_fails_the_bend_number() {
    let mut fixture = fixture("synthetic.countersinks_bent");
    let sink = fixture.input.facts.holes.as_mut().expect("holes")[0].countersink.as_mut().expect("a countersink");
    sink.bend_gaps[0].gap_mm = 0.5;
    let findings = run(&fixture);
    let found = codes(&findings);
    assert!(found.contains(&"COUNTERSINK_BEND_BELOW_LIMIT"), "{found:?}");
}

#[test]
fn a_countersink_with_no_land_is_reviewed_on_its_own() {
    let fixture = fixture("synthetic.countersinks_flat");
    let findings = run(&fixture);
    let no_land: Vec<&Finding> = findings.iter().filter(|finding| finding.error_code.as_deref() == Some("COUNTERSINK_NO_LAND")).collect();
    assert_eq!(no_land.len(), 1);
    assert_eq!(no_land[0].measured_mm, Some(0.0));
    assert!(no_land[0].requirement.is_none(), "no land means no depth to compare");
    assert_eq!(no_land[0].rules, vec!["sm.countersink_depth".to_string()]);
}
